"use server";

import { prisma } from "@/src/lib/prisma";
import { revalidatePath } from "next/cache";

export async function createNewTask(title: string, description: string) {
  try {
    const user = await prisma.user.findFirst();

    if (!user) {
      return { success: false, error: "Geen gebruiker gevonden." };
    }

    await prisma.task.create({
      data: {
        title,
        description,
        status: "TODO",
        priority: "MEDIUM",
        userId: user.id,
      },
    });

    revalidatePath("/");
    revalidatePath("/tasks");

    return { success: true };
  } catch (error) {
    console.error("Task Error:", error);
    return { success: false, error: "Fout bij opslaan." };
  }
}