"use client";

import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { createNewTask } from "@/app/actions/task-actions";
import { Loader2 } from "lucide-react"; // Yükleniyor ikonu için

export default function TaskFormModal({ open, setOpen }: any) {
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSave = async () => {
    if (!title) return alert("Titel is verplicht!");
    
    setLoading(true);
    const result = await createNewTask(title, description);
    
    if (result.success) {
      setTitle("");
      setDescription("");
      setOpen(false); // Modalı kapat
    } else {
      alert(result.error || "Er is iets misgegaan.");
    }
    setLoading(false);
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogContent className="bg-[#0E153A]/95 border border-teal-400/30 shadow-[0_0_50px_rgba(45,212,191,0.15)] backdrop-blur-xl p-8 rounded-[2rem] sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle className="text-3xl font-black bg-gradient-to-r from-teal-300 to-fuchsia-400 bg-clip-text text-transparent uppercase tracking-tight">
            Nieuwe Taak
          </DialogTitle>
          <p className="text-teal-400/50 text-sm mt-1 italic">Voeg een nieuwe uitdaging toe aan je lijst.</p>
        </DialogHeader>

        <div className="flex flex-col gap-6 mt-6">
          <div className="space-y-2">
            <label className="text-xs font-bold text-teal-400 uppercase ml-1 tracking-widest">Titel</label>
            <Input
              placeholder="Wat moet er gebeuren?"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="bg-[#070B24]/50 text-white border-teal-400/20 focus:border-fuchsia-400 transition-all h-12 rounded-xl"
            />
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold text-teal-400 uppercase ml-1 tracking-widest">Beschrijving</label>
            <Textarea
              placeholder="Details over deze taak..."
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="bg-[#070B24]/50 text-white border-teal-400/20 focus:border-fuchsia-400 transition-all min-h-[120px] rounded-xl resize-none"
            />
          </div>

          <div className="flex gap-3 mt-4">
            <Button
              variant="outline"
              onClick={() => setOpen(false)}
              className="flex-1 border-teal-400/20 text-teal-400 hover:bg-teal-400/10 h-12 rounded-xl font-bold"
            >
              Annuleren
            </Button>
            <Button
              onClick={handleSave}
              disabled={loading}
              className="flex-1 bg-gradient-to-r from-teal-400 to-fuchsia-400 text-[#070B24] font-black h-12 rounded-xl hover:scale-105 transition-all shadow-lg active:scale-95"
            >
              {loading ? (
                <Loader2 className="w-5 h-5 animate-spin" />
              ) : (
                "OPSLAAN"
              )}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}